inline const uint16_t* getMemeBitmap(uint8_t pack, uint8_t mood) {
    static const uint16_t* const MEME_TABLE[3][6] = {
        { meme_p0_mochi_m0_happy, meme_p0_mochi_m1_focus, meme_p0_mochi_m2_bug, meme_p0_mochi_m3_lowbat, meme_p0_mochi_m4_chill, meme_p0_mochi_m5_tgif },
        { meme_p1_star_m0_happy, meme_p1_star_m1_focus, meme_p1_star_m2_bug, meme_p1_star_m3_lowbat, meme_p1_star_m4_chill, meme_p1_star_m5_tgif },
        { meme_p2_bunny_m0_happy, meme_p2_bunny_m1_focus, meme_p2_bunny_m2_bug, meme_p2_bunny_m3_lowbat, meme_p2_bunny_m4_chill, meme_p2_bunny_m5_tgif },
    };
    if (pack >= 3) pack = 0;
    if (mood >= 6) mood = 0;
    return MEME_TABLE[pack][mood];
}

